from lib import *
S = SS('x14')
steps = [
    step("@Value 里的 #{...} 表达式(user 是容器里的 User Bean:name=alice、age=30、tags=[a,b,c]、score={math:90}、friend=null)。#{user.name.toUpperCase()} 得到 ALICE;#{user.age > 18 ? '成年' : '未成年'} 得到成年;#{user.tags[1]} 得到 b;#{user.score['math'] + 10} 得到 100;#{systemProperties['user.language']} 得到 en;#{T(java.lang.Math).max(3, 7)} 得到 7;#{user?.friend?.name} 得到 null(安全导航,不抛空指针);${missing:#{user.name}} 属性缺失时用 SpEL 做默认值,得到 alice。", t=tl(S(1)), mark=lidx(S(1), 'upper=ALICE'), b=bars([['表达式个数', 8, '8'], ['成功求值', 8, '8(无异常)'], ['user?.friend?.name', 0, 'null']], 8, done=[0, 1], mark=[2]), kv=KV([['引用 Bean', '#{user.name}'], ['调用静态方法', '#{T(java.lang.Math).max(3, 7)}'], ['安全导航', 'user?.friend?.name → null'], ['和占位符组合', '${missing:#{user.name}}']], ['安全导航'])),
    step("SpEL 的语法一览(对一个 User 求值)。name → alice,name.length() → 5,age * 2 + 1 → 61,tags.size() > 2 → true,tags[0] + tags[2] → ac,score['math'] → 90,hello('bob') → hello bob from alice,friend?.name → null,new String('x').toUpperCase() → X,T(java.lang.System).currentTimeMillis() > 0 → true,tags.![toUpperCase()](投影)→ [A, B, C],tags.?[#this != 'b'](过滤)→ [a, c],'abc' matches '[a-c]+' → true,#root.age → 30。出错的:friend.name(friend 是 null,没有 ?.)→ SpelEvaluationException EL1007E:Property or field 'name' cannot be found on null;private 的 secret 和不存在的 nope 都是 EL1008E:cannot be found on object of type 'demo.Main$User'。", t=tl(S(2)), mark=lidx(S(2), 'friend.name  ', 'secret  ', 'nope  '), done=lidx(S(2), 'name.length()', 'tags.![toUpperCase()]', 'tags.?[#this', "'abc' matches"), b=bars([['成功的表达式', 14, '14'], ['失败的表达式', 3, '3(friend.name、secret、nope)']], 14, done=[0], mark=[1]), kv=KV([['投影', 'tags.![toUpperCase()] → [A, B, C]'], ['过滤', 'tags.?[#this != "b"] → [a, c]'], ['null 上取属性', 'EL1007E,要用 ?.'], ['private 字段', 'EL1008E,取不到']], ['null 上取属性'])),
    step("谁来求值很重要。StandardEvaluationContext 下 T(java.lang.Runtime).getRuntime().availableProcessors() 返回 10(能调任意类的静态方法)。换成 SimpleEvaluationContext.forReadOnlyDataBinding(),同一个表达式失败:EL1005E:Type cannot be found 'java.lang.Runtime'。受限上下文里读 name 仍然得到 alice,赋值 name = 'x' 失败:EL1068E:The expression component 'name='x'' is not assignable。表达式来自用户输入时,不能用 StandardEvaluationContext。", t=tl(S(3)), mark=lidx(S(3), 'SimpleEvaluationContext.forReadOnlyDataBinding() 下同一个表达式', '只读上下文里赋值'), done=lidx(S(3), 'StandardEvaluationContext 下', 'SimpleEvaluationContext 读 name'), b=bars([['Standard:调 Runtime 静态方法', 1, '成功(返回 10)'], ['Simple:调 Runtime 静态方法', 0, 'EL1005E'], ['Simple:读 name', 1, 'alice'], ['Simple:赋值 name', 0, 'EL1068E']], 1, done=[0, 2], mark=[1, 3]), kv=KV([['StandardEvaluationContext', '能访问任意类型和方法'], ['SimpleEvaluationContext', '只读数据绑定,类型和方法受限'], ['T(...)', '在受限上下文里找不到类型'], ['用户输入的表达式', '必须用受限上下文']], ['用户输入的表达式'])),
    step("求值的成本(同一个表达式 age * 2 + 1,单线程预热之后,三次运行)。每次 parseExpression 再求值:1315、1227、1219 ns/次。解析一次后反复求值:96、96、96 ns/次。编译模式(SpelCompilerMode.IMMEDIATE):6.5、5.0、6.6 ns/次。直接写 Java:1.99、2.01、1.73 ns/次。每次都重新解析比复用解析结果慢约 13 倍(1315 对 96,算出的比值);编译模式把求值压到几 ns,接近直接写 Java 的量级。这是简单的循环计时,没有用 JMH,个位数 ns 的差别不能当精确值。", t=tl(S(4)), mark=lidx(S(4), '每次 parseExpression 加求值:1315'), b=bars([['每次解析并求值 ns', 1315, '1315'], ['解析一次再求值 ns', 96, '96'], ['编译模式 ns', 6.5, '6.5'], ['直接写 Java ns', 1.99, '1.99']], 1315, mark=[0], cur=[1], done=[2, 3]), kv=KV([['每次 parseExpression', '约 1200 到 1300 ns'], ['解析一次复用', '约 96 ns'], ['编译模式', '约 5 到 7 ns'], ['直接写 Java', '约 2 ns']], ['解析一次复用'])),
]
A = mkartx('x14', 14, 'Spring,SpEL,表达式语言,Value,真实验证,动画演示',
    '实测 SpEL:@Value("#{...}") 的引用 Bean、安全导航、静态方法调用、集合投影与过滤;null 上取属性抛 EL1007E;StandardEvaluationContext 能调 Runtime 的静态方法,SimpleEvaluationContext 拒绝;每次重新解析表达式约 1300 ns,复用解析结果约 96 ns,编译模式约 5 到 7 ns。',
    'SpEL 能写什么、在哪里被求值?表达式里出错会是什么样?用户输入的表达式为什么危险?每次解析和复用解析结果差多少?这篇在 Spring Framework 7.0.9 上逐项验证。',
    [('约 13 倍', '每次 parseExpression 与解析一次后反复求值的耗时比值(1315 对 96 ns,算出的比值)'), ('EL1005E', '受限的 SimpleEvaluationContext 下执行 T(java.lang.Runtime) 得到的错误'), ('5 到 7 ns', '编译模式(SpelCompilerMode.IMMEDIATE)每次求值的耗时')],
    [('@Value 里的表达式', '<p>可以引用 Bean、调用方法与静态方法,用 ?. 避免空指针,也能和 ${} 占位符组合。</p>'),
     ('语法与错误', '<p>集合投影与过滤、matches、三元;在 null 上取属性、取不到的字段都有明确的错误码。</p>'),
     ('求值上下文', '<p>Standard 上下文能访问任意类型,Simple 上下文把类型和写入都限制住。</p>'),
     ('成本', '<p>解析是大头,解析一次复用能省一个数量级,编译模式再省一个数量级。</p>')],
    steps,
    [ENV_X + '。用不带 Boot 的 Spring Framework 7.0.9;耗时是简单循环计时(预热之后),没有用 JMH,直接写 Java 的那一项在循环里可能被 JIT 部分优化,只能当量级参考;availableProcessors 返回的 10 是这台机器的核数',
     '没有验证:SpEL 在 @Cacheable、@PreAuthorize、@ConditionalOnExpression 里的使用;MethodBasedEvaluationContext;自定义函数与 PropertyAccessor;编译模式对非 public 类的限制;SpEL 在 AOT 下的支持;表达式注入的实际利用方式(只验证了受限上下文会拒绝)'],
    'SpEL 表达式')
